css:
.UIMenu,
.UIPanel {
  position: fixed;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  z-index: 100002;
}
.UIPanel {
  line-height: 14px;
  font-size: 14px;
  background-color: rgba(0, 0, 0, 0.25);
}
.UIPanel:after {
  display: inline-block;
  height: 100%;
  vertical-align: middle;
  content: "";
}
.UIPanel > div {
  -moz-box-sizing: border-box;
  box-sizing: border-box;
  display: inline-block;
  height: auto;
  max-height: 100%;
  position: relative;
  width: 400px;
  left: 50%;
  margin-left: -200px;
  overflow: auto;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.25);
  vertical-align: middle;
}
#settingsMenu > div {
  top: 25px;;
  vertical-align: top;
  max-height: 85%;
}
.extPanel input[type="text"],
.extPanel textarea {
  border: 1px solid #AAA;
  outline: none;
}
.UIPanel .center {
  margin-bottom: 5px;
}
.UIPanel button {
  display: inline-block;
  margin-right: 5px;
}
.UIPanel code {
  background-color: #eee;
  color: #000000;
  padding: 1px 4px;
  font-size: 12px;
}
.UIPanel ul {
  list-style: none;
  padding: 0;
  margin: 0 0 10px;
}
.UIPanel .export-field {
  width: 385px;
}

@media only screen and (max-width: 480px) {
.UIPanel > div {
  width: 320px;
  margin-left: -160px;
}
}
